# ==================== 安全回城 ====================
func _recall_safe_behavior(delta):
	# AI孙悟空：筋斗云飞行中不干预；落地后在泉水附近等待自动回血
	if hero.wukong_cloud_flying:
		return
	if hero.display_name == "孙悟空":
		var _spawn = Vector3(-60, 0, 60) if hero.team == Config.Team.PLAYER else Vector3(60, 0, -60)
		if hero.global_position.distance_to(_spawn) < AiConfig.SPAWN_LEAVE_RANGE:
			return
	# 已在泉水中 → 等待自动回血，由_decide恢复状态
	if hero.health>2000:
		hero.cancel_recall()

diffs.newText:
# ==================== 安全回城 ====================
func _recall_safe_behavior(delta):
	# 英雄特判（孙悟空筋斗云飞行中/已在泉水）→ 本英雄自行处理
	if brain.handle_recall_safe():
		return
	# 已在泉水中 → 等待自动回血，由_decide恢复状态
	if hero.health>2000:
		hero.cancel_recall()

