{"content":"extends Node

# 临时验证：难度表接线（名称/参数读取、预判提前量、落点误差量级）。
func _ready() -> void:
	var fails := 0

	AiConfig.difficulty = AiConfig.Difficulty.KING
	if AiConfig.difficulty_name() != "王者":
		fails += 1
		print("FAIL: 王者名称=", AiConfig.difficulty_name())
	if AiConfig.prediction_frames() != 3:
		fails += 1
		print("FAIL: 王者预判帧=", AiConfig.prediction_frames())
	if absf(AiConfig.skill_accuracy() - 1.0) > 0.0001:
		fails += 1
		print("FAIL: 王者精度=", AiConfig.skill_accuracy())

	AiConfig.difficulty = AiConfig.Difficulty.BRONZE
	if AiConfig.difficulty_name() != "青铜":
		fails += 1
		print("FAIL: 青铜名称=", AiConfig.difficulty_name())
	if absf(AiConfig.skill_accuracy() - 0.55) > 0.0001:
		fails += 1
		print("FAIL: 青铜精度=", AiConfig.skill_accuracy())

	var target = load("res://scripts/entities/Hero.gd").new()
	target.setup({"name": "亚瑟", "role": "战士", "max_health": 4000, "team": 1})
	target.position = Vector3(10, 0, 5)
	add_child(target)
	target.velocity = Vector3.ZERO

	var tactics = load("res://ai/tactics/SkillTactics.gd").new(null, null)

	# 王者：静止目标零误差
	AiConfig.difficulty = AiConfig.Difficulty.KING
	var aim: Vector3 = tactics._aim_pos(target)
	if aim != target.global_position:
		fails += 1
		print("FAIL: 王者对静止目标有误差 aim=", aim, " target=", target.global_position)

	# 王者：预判 3 帧 × 50ms = 0.15s，速度 10m/s → 提前 1.5m
	target.velocity = Vector3(0, 0, 10)
	var aim2: Vector3 = tactics._aim_pos(target)
	if absf(aim2.z - (target.global_position.z + 1.5)) > 0.01:
		fails += 1
		print("FAIL: 预判落点 z=", aim2.z, " 期望=", target.global_position.z + 1.5)
	target.velocity = Vector3.ZERO

	# 青铜：误差存在且不超过 (1-0.55)*3 = 1.35m
	AiConfig.difficulty = AiConfig.Difficulty.BRONZE
	var sum_d := 0.0
	var max_d := 0.0
	for i in range(300):
		var p: Vector3 = tactics._aim_pos(target)
		var d := p.distance_to(target.global_position)
		sum_d += d
		max_d = maxf(max_d, d)
	if sum_d / 300.0 <= 0.05:
		fails += 1
		print("FAIL: 青铜平均误差过小=", sum_d / 300.0)
	if max_d > 1.36:
		fails += 1
		print("FAIL: 青铜最大误差超上限=", max_d)

	# 黄金：误差上限 (1-0.88)*3 = 0.36m
	AiConfig.difficulty = AiConfig.Difficulty.GOLD
	var max_d2 := 0.0
	for i in range(300):
		max_d2 = maxf(max_d2, tactics._aim_pos(target).distance_to(target.global_position))
	if max_d2 > 0.37:
		fails += 1
		print("FAIL: 黄金最大误差超上限=", max_d2)

	print("DIFF_TEST_DONE fails=", fails)
	get_tree().quit(0 if fails == 0 else 1)
","file_path":".tmp\diff_test_node.gd"}

