# 临时验证：AiPerception 共享实体快照（TTL 内复用、过期重建、已释放实体过滤）。
func _ready() -> void:
	var HeroScript = load("res://scripts/entities/Hero.gd")
	var fails := 0

	var a = HeroScript.new()
	a.setup({"name": "亚瑟", "role": "战士", "max_health": 4000, "team": 0})
	a.position = Vector3(0, 0, 0)
	add_child(a)
	a.set_physics_process(false)
	a.set_process(false)

	var b = HeroScript.new()
	b.setup({"name": "后羿", "role": "射手", "max_health": 3200, "team": 1})
	b.position = Vector3(5, 0, 0)
	add_child(b)

	var p = load("res://ai/perception/AiPerception.gd").new(a)
	var r1: Array = p.query_in_range(20.0)
	if not r1.has(b):
		fails += 1
		print("FAIL: 快照应包含初始敌人 b，实际=", r1.size())
	print("step1 ok, r1=", r1.size())

	# TTL 内新增敌人不应立刻出现（缓存命中）
	var c = HeroScript.new()
	c.setup({"name": "兰陵王", "role": "刺客", "max_health": 3400, "team": 1})
	c.position = Vector3(0, 0, 5)
	add_child(c)
	var r2: Array = p.query_in_range(20.0)
	if r2.has(c):
		fails += 1
		print("FAIL: TTL 内应命中旧快照，但仍包含新敌人 c")
	if not r2.has(b):
		fails += 1
		print("FAIL: TTL 内旧快照应仍含 b")
	print("step2 ok, r2=", r2.size())

	# 过期后重建，新敌人出现
	await get_tree().create_timer(0.2).timeout
	var r3: Array = p.query_in_range(20.0)
	if not r3.has(c):
		fails += 1
		print("FAIL: 过期后应重建并包含新敌人 c，实际=", r3.size())
	if not r3.has(b):
		fails += 1
		print("FAIL: 过期后应仍含 b")
	print("step3 ok, r3=", r3.size())

	# 已释放实体被过滤
	b.queue_free()
	await get_tree().create_timer(0.2).timeout
	var r4: Array = p.query_in_range(20.0)
	if r4.has(b):
		fails += 1
		print("FAIL: 已释放实体不应出现在结果里")
	print("step4 ok, r4=", r4.size())

	print("PERCEPTION_TEST_DONE fails=", fails)
	get_tree().quit(0 if fails == 0 else 1)
