{"content":"extends Node

func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")
	var mage: Node = null
	var frames := 0
	while frames < 15000:
		await get_tree().process_frame
		frames += 1
		if mage == null or not is_instance_valid(mage):
			for h in get_tree().get_nodes_in_group("heroes"):
				if h.is_ai and h.team == Config.Team.PLAYER and h.role == "法师":
					mage = h
					break
		if mage and frames % 60 == 0:
			var ai: Node = null
			for c in mage.get_children():
				if c.has_method("_decide"):
					ai = c
					break
			var ls = ai.get("lane_strategy") if ai else null
			print("t=%.2f %s pos=(%.1f,%.1f) s=%.1f lane=%s lslane=%s switched=%s state=%s move=(%.1f,%.1f)" % [
				bm.game_time, mage.display_name, mage.global_position.x, mage.global_position.z,
				mage.global_position.x + mage.global_position.z,
				str(ai.get("lane")) if ai else "?", str(ls.get("lane")) if ls else "?",
				str(ls.get("mid_switched_lane")) if ls else "?",
				str(ai.get("state")) if ai else "?",
				mage.move_target.x, mage.move_target.z])
		if bm.game_time > 12.0:
			break
	print("MAGE_TEST_DONE")
	get_tree().quit(0)
","file_path":".tmp\mage_test_node.gd"}

