# 验证：防御塔快照缓存里残留已释放塔时，查询不得抛 "Left operand of 'is' is a previously freed instance"
func _ready() -> void:
	var HeroScript = load("res://scripts/entities/Hero.gd")
	var TurretScript = load("res://scripts/entities/Turret.gd")
	var fails := 0

	var h = HeroScript.new()
	h.setup({"name": "亚瑟", "role": "战士", "max_health": 4000, "team": 0})
	h.position = Vector3(0, 0, 0)
	add_child(h)
	h.set_physics_process(false)
	h.set_process(false)

	var t = TurretScript.new()
	t.setup({"team": 0, "max_health": 3000, "attack": 100, "attack_range": 890})
	t.position = Vector3(0, 0, 10)
	add_child(t)
	t.set_physics_process(false)
	t.set_process(false)
	t.health = 3000.0
	t.team = 0

	var p = load("res://ai/perception/AiPerception.gd").new(h)
	var near = p.find_nearest_friendly_turret(40.0)
	if near == null:
		fails += 1
		print("FAIL: 应找到己方塔")

	# 缓存刚建立后立刻释放塔 → TTL 内再查会命中旧快照
	t.queue_free()
	await get_tree().process_frame
	var near2 = p.find_nearest_friendly_turret(40.0)
	print("stale turret query=", near2)
	if near2 != null:
		fails += 1
		print("FAIL: 已释放的塔不应被返回")

	await get_tree().create_timer(0.5).timeout
	var near3 = p.find_nearest_friendly_turret(40.0)
	print("rebuilt turret query=", near3)

	print("TURRET_STALE_DONE fails=", fails)
	get_tree().quit(0 if fails == 0 else 1)
","file_path":".tmp\turret_stale_node.gd"}

