	var last_sample := -1.0
	var prev := {}      # id -> {pos, wp, away_timer}
	var anomalies := 0
	var frames := 0
	while frames < 200000:
		await get_tree().process_frame
		frames += 1
		if bm.game_time - last_sample < 0.25:
			continue
		last_sample = bm.game_time
		for m in get_tree().get_nodes_in_group("minions"):
			if not is_instance_valid(m) or m.team != Config.Team.ENEMY or m.health <= 0:
				continue
			var id: int = m.get_instance_id()
			var wp_idx: int = m.waypoint_index
			var wp: Vector3 = m.waypoints[wp_idx] if wp_idx < m.waypoints.size() else m.global_position
			var p: Vector3 = m.global_position
			var rec = prev.get(id)
			if rec != null:
				var moved: float = p.distance_to(rec["pos"])
				var to_wp: Vector3 = wp - p
				to_wp.y = 0
				var mv: Vector3 = p - rec["pos"]
				mv.y = 0
				var target_name := ""
				if is_instance_valid(m.current_target):
					target_name = str(m.current_target.display_name)
				var away := false
				if moved > 0.05 and to_wp.length() > 1.0 and mv.length() > 0.02:
					if mv.normalized().dot(to_wp.normalized()) < -0.3:
						away = true
				var stuck := moved < 0.05 and target_name == "" and wp_idx == rec["wp"]
				if stuck or away:
					anomalies += 1
					print("[ANOMALY t=%.1f] id=%d line=%d name=%s pos=(%.1f,%.1f) wp=%d wp_pos=(%.1f,%.1f) moved=%.2f away=%s stuck=%s target=%s" % [
						bm.game_time, id % 100000, m.line, m.display_name, p.x, p.z,
						wp_idx, wp.x, wp.z, moved, str(away), str(stuck), target_name])
			prev[id] = {"pos": p, "wp": wp_idx}
		if bm.game_time > 55.0:
			break
	print("MINION_SCAN_DONE anomalies=%d frames=%d" % [anomalies, frames])
	get_tree().quit(0)
