# 追踪卡住的小兵：卡住超过 0.5 秒后逐帧打印细节，看是撞墙/推挤/A*失败/路点不可达
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")

	var last_sample := -1.0
	var prev := {}
	var stuck_frames := {}
	var reported := {}
	var frames := 0
	while frames < 200000:
		await get_tree().process_frame
		frames += 1
		if bm.game_time - last_sample < 0.25:
			continue
		last_sample = bm.game_time
		for m in get_tree().get_nodes_in_group("minions"):
			if not is_instance_valid(m) or m.team != Config.Team.ENEMY or m.health <= 0:
				continue
			var id: int = m.get_instance_id()
			var p: Vector3 = m.global_position
			var rec = prev.get(id)
			if rec != null:
				var moved: float = p.distance_to(rec["pos"])
				var tname := ""
				if is_instance_valid(m.current_target):
					tname = str(m.current_target.display_name)
				if moved < 0.05 and tname == "":
					stuck_frames[id] = int(stuck_frames.get(id, 0)) + 1
				else:
					stuck_frames[id] = 0
			prev[id] = {"pos": p}
			if int(stuck_frames.get(id, 0)) >= 2 and int(reported.get(id, 0)) < 12:
				reported[id] = int(reported.get(id, 0)) + 1
				var wp_idx: int = m.waypoint_index
				var wp: Vector3 = m.waypoints[wp_idx] if wp_idx < m.waypoints.size() else m.global_position
				var near_minion := 0
				for o in get_tree().get_nodes_in_group("minions"):
					if o == m or not is_instance_valid(o):
						continue
					if o.global_position.distance_to(p) < 1.6:
						near_minion += 1
				var near_turret := ""
				for tu in get_tree().get_nodes_in_group("turrets"):
					if is_instance_valid(tu) and tu.global_position.distance_to(p) < 4.0:
						near_turret = "%s(%.0f,%.0f)" % [tu.display_name, tu.global_position.x, tu.global_position.z]
				print("[STUCK t=%.1f] %s line=%d pos=(%.1f,%.1f) wp=%d/%d wp_pos=(%.1f,%.1f) stuck_frames=%d stuck_t=%.2f rec_dir=(%.2f,%.2f) nav_path=%d nav_idx=%d nav_last=%s rot=%.1f near_minion=%d near_turret=%s" % [
					bm.game_time, m.display_name, m.line, p.x, p.z, wp_idx, m.waypoints.size(), wp.x, wp.z,
					int(stuck_frames.get(id, 0)), m._stuck_timer, m._stuck_recovery_dir.x, m._stuck_recovery_dir.z,
					m._nav_path.size(), m._nav_index,
					str(m._nav_path[m._nav_path.size() - 1]) if m._nav_path.size() > 0 else "empty",
					rad_to_deg(m.rotation.y), near_minion, near_turret])
		if bm.game_time > 55.0:
			break
	print("STUCK_SCAN_DONE frames=%d" % frames)
	get_tree().quit(0)
","file_path":".tmp\minion_stuck_node.gd"}

