# 诊断：卡在地图边缘(z=-60)的红方小兵 A* 为什么返回空路径
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")

	var frames := 0
	var found: Node = null
	while frames < 200000:
		await get_tree().process_frame
		frames += 1
		if bm.game_time < 24.0:
			continue
		for m in get_tree().get_nodes_in_group("minions"):
			if is_instance_valid(m) and m.team == Config.Team.ENEMY and m.global_position.z < -59.4:
				found = m
				break
		if found != null:
			break
	if found == null:
		print("DIAG_DONE no minion found")
		get_tree().quit(0)
		return

	var p: Vector3 = found.global_position
	var goal: Vector3 = found.waypoints[found.waypoint_index]
	print("minion pos=", p, " wp=", found.waypoint_index, " goal=", goal, " stuck_t=", found._stuck_timer)
	var fc = PathFinder._world_to_cell(p)
	var tc = PathFinder._world_to_cell(goal)
	print("cells from=", fc, " in_bounds=", PathFinder._is_in_bounds(fc), " solid=", PathFinder.astar.is_point_solid(fc),
		" | to=", tc, " in_bounds=", PathFinder._is_in_bounds(tc), " solid=", PathFinder.astar.is_point_solid(tc))
	print("cell_min=", PathFinder.CELL_MIN, " cell_max=", PathFinder.CELL_MAX, " grid_half=", PathFinder.GRID_HALF)
	for dz in [0.0, -0.5, -1.0, 1.0]:
		var fp := Vector3(p.x, 0, p.z + dz)
		var r = PathFinder.find_path(fp, goal, (goal - fp).normalized(), -1, -1.0, Vector3.ZERO)
		print("path from z=%.1f size=%d first=%s" % [fp.z, r.size(), str(r[0]) if r.size() > 0 else "-"])
	var nb = PathFinder._find_nearest_walkable(fc, Vector2i.ZERO)
	print("nearest walkable of from=", nb, " solid=", PathFinder.astar.is_point_solid(nb))
	print("DIAG_DONE")
	get_tree().quit(0)
","file_path":".tmp\edge_diag_node.gd"}

