{"content":"extends Node

# 1) 全程扫描红方小兵异常移动；2) 强制把一个小兵丢到地图边界(z=-60)看能否自行走出来
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")

	var last_sample := -1.0
	var prev := {}
	var anomalies := 0
	var frames := 0
	while bm.game_time < 40.0 and frames < 200000:
		await get_tree().process_frame
		frames += 1
		if bm.game_time - last_sample < 0.25:
			continue
		last_sample = bm.game_time
		for m in get_tree().get_nodes_in_group("minions"):
			if not is_instance_valid(m) or m.team != Config.Team.ENEMY or m.health <= 0:
				continue
			var p: Vector3 = m.global_position
			var rec = prev.get(m.get_instance_id())
			if rec != null:
				var moved: float = p.distance_to(rec["pos"])
				var tname := ""
				if is_instance_valid(m.current_target):
					tname = str(m.current_target.display_name)
				var wp_idx: int = m.waypoint_index
				var wp: Vector3 = m.waypoints[wp_idx] if wp_idx < m.waypoints.size() else p
				var mv: Vector3 = p - rec["pos"]
				mv.y = 0
				var to_wp: Vector3 = wp - p
				to_wp.y = 0
				var away := false
				if moved > 0.05 and to_wp.length() > 1.0 and mv.length() > 0.02:
					away = mv.normalized().dot(to_wp.normalized()) < -0.3
				var stuck: bool = moved < 0.05 and tname == "" and wp_idx == int(rec["wp"])
				if stuck or away:
					anomalies += 1
					print("[ANOMALY t=%.1f] %s line=%d pos=(%.1f,%.1f) wp=%d moved=%.2f away=%s stuck=%s target=%s" % [
						bm.game_time, m.display_name, m.line, p.x, p.z, wp_idx, moved, str(away), str(stuck), tname])
			prev[m.get_instance_id()] = {"pos": p, "wp": m.waypoint_index}
	print("SCAN_DONE anomalies=%d" % anomalies)

	# 强制边界回归测试
	var test_m: Node = null
	for m in get_tree().get_nodes_in_group("minions"):
		if is_instance_valid(m) and m.team == Config.Team.ENEMY and m.line == 2:
			test_m = m
			break
	if test_m == null:
		print("EDGE_TEST skip (no minion)")
		get_tree().quit(0)
		return
	var wp3 := Vector3(-58, 0, -28)
	var idx := -1
	for i in range(test_m.waypoints.size()):
		if test_m.waypoints[i].distance_to(wp3) < 0.5:
			idx = i
	if idx >= 0:
		test_m.waypoint_index = idx
	test_m.global_position = Vector3(-27.3, 0, -60.0)
	var z0: float = test_m.global_position.z
	await get_tree().create_timer(2.0).timeout
	var z1: float = test_m.global_position.z
	var nav_ok: bool = test_m._nav_path.size() > 0
	print("EDGE_TEST z0=%.2f z1=%.2f moved_in=%s nav_path_ok=%s" % [z0, z1, str(z1 > -59.2 and z1 > z0), str(nav_ok)])
	print("MINION_FIX_DONE")
	get_tree().quit(0)
","file_path":".tmp\minion_fix_node.gd"}

