# 逐帧追踪被丢到边界的那个小兵，找出它为什么停住
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")

	var frames := 0
	while bm.game_time < 3.0 and frames < 200000:
		await get_tree().process_frame
		frames += 1
	var m: Node = null
	for x in get_tree().get_nodes_in_group("minions"):
		if is_instance_valid(x) and x.team == Config.Team.ENEMY and x.line == 2 and x.health > 0:
			m = x
			break
	if m == null:
		print("DIAG2_DONE no minion")
		get_tree().quit(0)
		return
	var idx := -1
	for i in range(m.waypoints.size()):
		if m.waypoints[i].distance_to(Vector3(-58, 0, -28)) < 0.5:
			idx = i
	if idx >= 0:
		m.waypoint_index = idx
	m.global_position = Vector3(-27.3, 0, -60.0)
	print("DIAG2 start wp_idx=%d wp=%s waypoints=%d" % [m.waypoint_index, str(m.waypoints[m.waypoint_index]), m.waypoints.size()])

	for f in range(180):
		await get_tree().process_frame
		if f % 15 != 0:
			continue
		if not is_instance_valid(m):
			print("DIAG2 died")
			break
		var nav_first := "-"
		if m._nav_path.size() > 0:
			nav_first = "(%.1f,%.1f)" % [m._nav_path[0].x, m._nav_path[0].z]
		var walls_near := 0
		for w in get_tree().get_nodes_in_group("walls"):
			if is_instance_valid(w) and w.global_position.distance_to(m.global_position) < 2.5:
				walls_near += 1
		var towers_near := ""
		for t in get_tree().get_nodes_in_group("turrets"):
			if is_instance_valid(t) and t.global_position.distance_to(m.global_position) < 3.2:
				towers_near += "%s(%.0f,%.0f)d=%.1f " % [t.display_name, t.global_position.x, t.global_position.z, t.global_position.distance_to(m.global_position)]
		print("f=%d pos=(%.2f,%.2f) wp=%d stuck_t=%.2f rec=(%.2f,%.2f) nav=%d idx=%d first=%s walls=%d towers=%s rot=%.0f" % [
			f, m.global_position.x, m.global_position.z, m.waypoint_index, m._stuck_timer,
			m._stuck_recovery_dir.x, m._stuck_recovery_dir.z, m._nav_path.size(), m._nav_index, nav_first,
			walls_near, towers_near, rad_to_deg(m.rotation.y)])
	print("DIAG2_DONE")
	get_tree().quit(0)
","file_path":".tmp\minion_diag2_node.gd"}

