# 长时扫描红方小兵：只报“连续≥3次采样(≥0.75s)”的卡住/背离，且要求当时没有攻击目标（战斗走位不算异常）
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")

	var last_sample := -1.0
	var prev := {}
	var bad := {}      # id -> 连续异常采样数
	var shoe := {}     # id -> 上次上报的连续计数
	var anomalies := 0
	var frames := 0
	while bm.game_time < 45.0 and frames < 400000:
		await get_tree().process_frame
		frames += 1
		if bm.game_time - last_sample < 0.25:
			continue
		last_sample = bm.game_time
		for m in get_tree().get_nodes_in_group("minions"):
			if not is_instance_valid(m) or m.team != Config.Team.ENEMY or m.health <= 0:
				continue
			var id: int = m.get_instance_id()
			var p: Vector3 = m.global_position
			var tname := ""
			if is_instance_valid(m.current_target):
				tname = str(m.current_target.display_name)
			var rec = prev.get(id)
			var bad_flag := false
			if rec != null and tname == "":
				var moved: float = p.distance_to(rec["pos"])
				var wp_idx: int = m.waypoint_index
				var wp: Vector3 = m.waypoints[wp_idx] if wp_idx < m.waypoints.size() else p
				var mv: Vector3 = p - rec["pos"]
				mv.y = 0
				var to_wp: Vector3 = wp - p
				to_wp.y = 0
				var away := false
				if moved > 0.05 and to_wp.length() > 1.0 and mv.length() > 0.02:
					away = mv.normalized().dot(to_wp.normalized()) < -0.3
				var stuck: bool = moved < 0.05 and wp_idx == int(rec["wp"])
				bad_flag = stuck or away
			bad[id] = int(bad.get(id, 0)) + 1 if bad_flag else 0
			if int(bad[id]) >= 3 and int(shoe.get(id, 0)) < int(bad[id]):
				shoe[id] = int(bad[id])
				anomalies += 1
				var wp_idx: int = m.waypoint_index
				var wp: Vector3 = m.waypoints[wp_idx] if wp_idx < m.waypoints.size() else p
				print("[BAD t=%.1f] %s line=%d pos=(%.1f,%.1f) wp=%d/%d wp_pos=(%.1f,%.1f) streak=%d" % [
					bm.game_time, m.display_name, m.line, p.x, p.z, wp_idx, m.waypoints.size(), wp.x, wp.z, int(bad[id])])
			prev[id] = {"pos": p, "wp": m.waypoint_index}
	print("SCAN3_DONE bad_reports=%d game_time=%.1f" % [anomalies, bm.game_time])
	get_tree().quit(0)
