# 验证低血量屏幕效果：PostFX 的 low_hp 强度与心跳脉冲随本地英雄血量变化
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")
	var frames := 0
	while bm.game_time < 2.0 and frames < 100000:
		await get_tree().process_frame
		frames += 1

	var h = bm.hero
	if h == null or not is_instance_valid(h):
		print("LOWHP_DONE ok=false reason=no hero")
		get_tree().quit(1)
		return
	var pfx = get_tree().root.get_node_or_null("PostFX")
	if pfx == null:
		print("LOWHP_DONE ok=false reason=no PostFX")
		get_tree().quit(1)
		return
	var mat = pfx.get("_mat")

	# 1) 20% 血：应进入低血状态，且心跳脉冲在动
	var pulses := {}
	for i in range(30):
		h.health = h.actual_max_health * 0.20
		await get_tree().process_frame
	var low_k: float = float(mat.get_shader_parameter("low_hp"))
	for i in range(40):
		h.health = h.actual_max_health * 0.20
		await get_tree().process_frame
		pulses[snappedf(float(mat.get_shader_parameter("low_hp_pulse")), 0.01)] = true
	var pulse_animated: bool = pulses.size() >= 3

	# 2) 满血：效果应消失
	for i in range(20):
		h.health = h.actual_max_health
		await get_tree().process_frame
	var high_k: float = float(mat.get_shader_parameter("low_hp"))

	# 3) 濒死 5%：强度应接近 1
	for i in range(20):
		h.health = h.actual_max_health * 0.05
		await get_tree().process_frame
	var crit_k: float = float(mat.get_shader_parameter("low_hp"))

	var ok: bool = low_k > 0.3 and low_k < 0.6 and pulse_animated and high_k <= 0.001 and crit_k > 0.9
	print("LOWHP low@20%%=%.3f crit@5%%=%.3f full=%.3f pulses=%d animated=%s" % [
		low_k, crit_k, high_k, pulses.size(), str(pulse_animated)])
	print("LOWHP_DONE ok=%s" % str(ok))
	get_tree().quit(0 if ok else 1)
","file_path":".tmp\lowhp_node.gd"}

