{"content":"extends Node

# 探针：确认 PostFX 是否真的在渲染，以及 low_hp 参数/角像素变化
func _grab(name: String) -> Image:
	await RenderingServer.frame_post_draw
	var img: Image = get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/%s.png" % name)
	return img

func _px(img: Image, x: int, y: int) -> String:
	var c: Color = img.get_pixel(x, y)
	return "(%d,%d,%d)" % [int(c.r * 255), int(c.g * 255), int(c.b * 255)]

func _ready() -> void:
	var pfx = get_tree().root.get_node_or_null("PostFX")
	print("PROBE postfx=%s mat=%s" % [str(pfx != null), str(pfx != null and pfx.get("_mat") != null)])
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")
	for i in range(150):
		await get_tree().process_frame
	var h = bm.hero
	var mat = pfx.get("_mat")

	for i in range(6):
		h.health = h.actual_max_health
		await get_tree().process_frame
	var img_full = await _grab("probe_full")
	print("PROBE full hp=%.2f low_hp=%.3f pulse=%.3f px=%s" % [
		float(h.health) / maxf(float(h.actual_max_health), 1.0),
		float(mat.get_shader_parameter("low_hp")), float(mat.get_shader_parameter("low_hp_pulse")),
		_px(img_full, 8, 8)])

	for i in range(6):
		h.health = h.actual_max_health * 0.05
		await get_tree().process_frame
	var img_low = await _grab("probe_low")
	print("PROBE low hp=%.2f low_hp=%.3f pulse=%.3f px=%s" % [
		float(h.health) / maxf(float(h.actual_max_health), 1.0),
		float(mat.get_shader_parameter("low_hp")), float(mat.get_shader_parameter("low_hp_pulse")),
		_px(img_low, 8, 8)])

	# 对照：直接用已有 dead 参数验证 PostFX 覆盖层是否渲染（去饱和应明显改变画面）
	pfx.set_dead(true)
	for i in range(6):
		h.health = h.actual_max_health
		await get_tree().process_frame
	pfx.set_dead(true)
	var img_dead = await _grab("probe_dead")
	print("PROBE dead px=%s dead_param=%.2f" % [_px(img_dead, 8, 8), float(mat.get_shader_parameter("dead"))])
	print("PROBE_DONE")
	get_tree().quit(0)
","file_path":".tmp\lowhp_probe_node.gd"}

