storm_shield_amount = 0.0
if storm_aura_active:
storm_aura_timer -= delta
if storm_aura_timer <= 0:
storm_aura_active = false
if storm_aura_ring:
storm_aura_ring.queue_free()
storm_aura_ring = null
else:
storm_aura_tick -= delta
if storm_aura_tick <= 0:
storm_aura_tick = 1.0
