# 移动端闪退诊断：长时间自动战斗，采样对象/内存增长趋势
func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")

	var next_report := 30.0
	var start_static := Performance.get_monitor(Performance.MEMORY_STATIC)
	var start_nodes := int(get_tree().get_node_count())
	print("SAMPLE t=0 nodes=%d orphan=%d objects=%d res=%d mem=%.1fMB" % [
		start_nodes,
		int(Performance.get_monitor(Performance.OBJECT_ORPHAN_NODE_COUNT)),
		int(Performance.get_monitor(Performance.OBJECT_COUNT)),
		int(Performance.get_monitor(Performance.OBJECT_RESOURCE_COUNT)),
		start_static / 1048576.0])
	var frames := 0
	while bm.game_time < 900.0:
		await get_tree().process_frame
		frames += 1
		if bm.game_time >= next_report:
			var st := Performance.get_monitor(Performance.MEMORY_STATIC)
			var nodes := int(get_tree().get_node_count())
			var orph := int(Performance.get_monitor(Performance.OBJECT_ORPHAN_NODE_COUNT))
			var obj := int(Performance.get_monitor(Performance.OBJECT_COUNT))
			var res := int(Performance.get_monitor(Performance.OBJECT_RESOURCE_COUNT))
			var proc := Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0
			var phys := Performance.get_monitor(Performance.TIME_PHYSICS) * 1000.0
			print("SAMPLE t=%.0f nodes=%d orphan=%d objects=%d res=%d mem=%.1fMB (+%.1f) proc=%.2fms phys=%.2fms frames=%d" % [
				bm.game_time, nodes, orph, obj, res, st / 1048576.0,
				(st - start_static) / 1048576.0, proc, phys, frames])
			next_report += 60.0
		if frames > 40000:
			print("SAMPLE aborted at frame cap t=%.0f" % bm.game_time)
			break
	print("SAMPLE_DONE")
	get_tree().quit(0)
","file_path":".tmp\mem_sampler.gd"}

