# 复活/观战部件：状态变化时是否正确重建（修复后回归）
func _count_widgets() -> int:
	var n := 0
	for row in UiManager.respawn_container.get_children():
		n += row.get_child_count()
	return n

func _ready() -> void:
	var bm = load("res://scenes/battle.tscn").instantiate()
	add_child(bm)
	await get_tree().process_frame
	await get_tree().process_frame
	bm._start_game_body("亚瑟", "flash")
	for i in range(60):
		await get_tree().process_frame
	var h = bm.hero
	print("RESPAWN_UI initial rows=%d widgets=%d" % [UiManager.respawn_container.get_child_count(), _count_widgets()])
	# 玩家阵亡
	h.take_damage(999999.0, null, true, -54, 1.0)
	for i in range(10):
		await get_tree().process_frame
	print("RESPAWN_UI dead rows=%d widgets=%d player_dead=%s" % [
		UiManager.respawn_container.get_child_count(), _count_widgets(), str(h.is_dead)])
	# 观战一名存活队友
	var ally = null
	for x in get_tree().get_nodes_in_group("heroes"):
		if is_instance_valid(x) and Config.is_ally(x.team) and x != h and not x.is_dead:
			ally = x
			break
	if ally != null:
		bm.set_spectate_target(ally)
		for i in range(6):
			await get_tree().process_frame
		var spectating_ok := false
		for row in UiManager.respawn_container.get_children():
			for w in row.get_children():
				if w is UiManager.RespawnWidget and w.hero == ally and w.spectating:
					spectating_ok = true
		print("RESPAWN_UI spectate ok=%s spec_set=%s" % [str(spectating_ok), str(bm.spectate_hero == ally)])
	# 敌方阵亡 → 第二排
	var enemy = null
	for x in get_tree().get_nodes_in_group("heroes"):
		if is_instance_valid(x) and not Config.is_ally(x.team) and not x.is_dead:
			enemy = x
			break
	if enemy != null:
		enemy.take_damage(999999.0, h, true, -54, 1.0)
		for i in range(8):
			await get_tree().process_frame
		print("RESPAWN_UI enemy_dead rows=%d widgets=%d" % [UiManager.respawn_container.get_child_count(), _count_widgets()])
	# 玩家复活（直接改状态模拟）
	h.is_dead = false
	h.health = h.actual_max_health
	h.respawn_timer = 0.0
	for i in range(8):
		await get_tree().process_frame
	print("RESPAWN_UI revived rows=%d widgets=%d player_dead=%s spec=%s" % [
		UiManager.respawn_container.get_child_count(), _count_widgets(), str(h.is_dead), str(bm.spectate_hero)])
	# 再跑 3 秒，确认孤儿节点不再增长
	var o0 := int(Performance.get_monitor(Performance.OBJECT_ORPHAN_NODE_COUNT))
	for i in range(180):
		await get_tree().process_frame
	var o1 := int(Performance.get_monitor(Performance.OBJECT_ORPHAN_NODE_COUNT))
	print("RESPAWN_UI orphan_delta_3s=%d (%d -> %d)" % [o1 - o0, o0, o1])
	print("RESPAWN_UI_DONE")
	get_tree().quit(0)
","file_path":".tmp\respawn_ui_test.gd"}

