## 验证「上次运行结尾」逻辑（res:// 版本，本地可写）

const CUR := "res://.tmp/diag_cur_test.log"

func _take_prev() -> String:
	if not FileAccess.file_exists(CUR):
		return ""
	var f := FileAccess.open(CUR, FileAccess.READ)
	if f == null:
		return ""
	var txt := f.get_as_text()
	f = null
	DirAccess.remove_absolute(ProjectSettings.globalize_path(CUR))
	if txt.length() > 1600:
		txt = txt.substr(txt.length() - 1600)
	return txt.strip_edges()

func _ready() -> void:
	var prev := _take_prev()
	print("PREV_LEN=", prev.length())
	if prev != "":
		print("PREV_TAIL=", prev.split("\n")[-1])
	var f := FileAccess.open(CUR, FileAccess.WRITE)
	if f == null:
		print("OPEN_FAIL=", FileAccess.get_open_error())
		get_tree().quit(1)
		return
	for i in 5:
		f.store_line("t=%d line" % i)
		f.flush()
	f = null
	print("WROTE_OK")
	get_tree().quit(0)
","file_path":".tmp\diag_prev_test.gd"}

