{"file_path":"scripts\core\SfxManager.gd","new_string":"# 回城引导循环：2s 无缝（所有分音都是 0.5Hz 整数倍，首尾相位连续）
func _build_recall_loop() -> AudioStreamWAV:
	var rate := 22050
	var dur := 2.0
	var n := int(dur * rate)
	var freqs := [110.0, 220.0, 261.5, 329.5, 440.0, 659.0]
	var gains := [0.22, 0.20, 0.16, 0.13, 0.10, 0.05]
	var data := PackedByteArray()
	data.resize(n * 2)
	for i in n:
		var t := float(i) / float(rate)
		var s := 0.0
		for j in freqs.size():
			s += sin(TAU * freqs[j] * t) * gains[j]
		s *= 0.55 * (0.72 + 0.28 * sin(TAU * 0.5 * t))   # 音量 + 2s 一个呼吸周期
		data.encode_s16(i * 2, int(clampf(s, -1.0, 1.0) * 32767.0))
	var st := AudioStreamWAV.new()
	st.format = AudioStreamWAV.FORMAT_16_BITS
	st.mix_rate = rate
	st.stereo = false
	st.data = data
	st.loop_mode = AudioStreamWAV.LOOP_FORWARD
	st.loop_begin = 0
	st.loop_end = n
	_pad_loop_tail(st, n)
	return st","old_string":"# 回城引导循环：2s 无缝（所有分音都是 0.5Hz 整数倍，首尾相位连续）
