func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	if bm == null:
		print("NO_BM")
		get_tree().quit(1)
		return
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 2.0 and guard < 3000:
		guard += 1
		await get_tree().process_frame
	var p: Dictionary = BattleHistory.payload_from_battle(bm)
	print("BATTLE_ROWS=", (p.get("rows", []) as Array).size(), " winner=", int(p.get("winner", -1)), " dur=%.2f" % float(p.get("dur", 0.0)))
	bm.crystal_destroyed(Config.Team.ENEMY)
	await get_tree().process_frame
	var panel_found := false
	for c in bm.get_children():
		if c is ResultsPanel:
			panel_found = true
	print("GAME_OVER=", bool(bm.get("game_over")), " results_panel=", panel_found)
	print("BATTLE_HISTORY_OK")
	get_tree().quit(0)
