{"file_path":"scripts\net\NetClientBattle.gd","new_string":"	func _draw_hero_bar(r: Dictionary) -> void:
		var cx := float(r.cx)
		# 主机 HUD：position = 锚点屏幕位 - custom_minimum_size/2（HeroInfoControl 高 320 → /2=160）
		var top := float(r.cy) - 160.0
