{"content":"extends Node

func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	if bm == null:
		print("NO_BM")
		get_tree().quit(1)
		return
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 3.0 and guard < 4000:
		guard += 1
		await get_tree().process_frame
	var h = bm.get("hero")
	h.is_mvp = true
	h.hidden_in_bush = true
	await get_tree().process_frame
	await get_tree().process_frame
	print("HOST_BAR_TEST mvp=", bool(h.is_mvp), " hidden=", bool(h.hidden_in_bush), " gt=%.1f" % float(bm.get("game_time")))
	var net_script = load("res://scripts/net/NetClientBattle.gd")
	print("NET_CLIENT_SCRIPT=", net_script != null)
	var sess_script = load("res://scripts/net/NetSession.gd")
	print("NET_SESSION_SCRIPT=", sess_script != null)
	print("BAR_VISUAL_OK")
	get_tree().quit(0)
","file_path":".tmp\bar_visual_test.gd"}

