	var name_h: float = font.get_multiline_string_size("亚瑟", HORIZONTAL_ALIGNMENT_LEFT, -1, 34).y
	var bar_top: float = 40.0 + 66.0 + name_h + 10.0
	var ring_c := Vector2(200.0 + 86.0, bar_top + 14.0)
	var hidden_c := Vector2(200.0 + 260.0, bar_top - 13.0)
	var mvp_c := Vector2(200.0 + 430.5, bar_top + 14.0)
	var old_ring_c := Vector2(200.0 + 260.0, 40.0 + 17.0)
	print("GEO bar_top=%.1f ring=%s hidden=%s mvp=%s old_ring=%s" % [bar_top, str(ring_c), str(hidden_c), str(mvp_c), str(old_ring_c)])

	var img := _sub.get_texture().get_image()
	img.save_png("res://.tmp/shot/bar_px.png")

	# 环：金色经验弧 + 灰底环
	print("CHECK_RING_GOLD=", _count(img, ring_c, 18.0, 30.0, func(c: Color) -> bool:
		return c.r > 0.75 and c.g > 0.60 and c.b < 0.55))
	print("CHECK_RING_GRAY=", _count(img, ring_c, 18.0, 30.0, func(c: Color) -> bool:
		return absf(c.r - c.g) < 0.12 and absf(c.g - c.b) < 0.12 and c.r > 0.35 and c.r < 0.75))
	# 旧位置（血条上方居中）不该再有环
	print("CHECK_OLD_RING=", _count(img, old_ring_c, 0.0, 24.0, func(c: Color) -> bool:
		return c.r > 0.75 and c.g > 0.60 and c.b < 0.55))
	# 隐藏图标：淡青眼睛 + 红色斜杠
	print("CHECK_HIDDEN_CYAN=", _count(img, hidden_c, 0.0, 14.0, func(c: Color) -> bool:
		return c.b > 0.65 and c.g > 0.60 and c.r < 0.72))
	print("CHECK_HIDDEN_RED=", _count(img, hidden_c, 0.0, 14.0, func(c: Color) -> bool:
		return c.r > 0.80 and c.g < 0.62 and c.b < 0.60))
	# MVP 王冠在血条右端
	print("CHECK_MVP_GOLD=", _count(img, mvp_c, 0.0, 22.0, func(c: Color) -> bool:
		return c.r > 0.85 and c.g > 0.62 and c.b < 0.55))
	print("PX_CHECK_DONE")
	get_tree().quit(0)


func _count(img: Image, c: Vector2, rmin: float, rmax: float, pred: Callable) -> int:
	var n := 0
	var x0 := int(maxf(0.0, c.x - rmax))
	var x1 := int(minf(float(img.get_width() - 1), c.x + rmax))
	var y0 := int(maxf(0.0, c.y - rmax))
	var y1 := int(minf(float(img.get_height() - 1), c.y + rmax))
	for y in range(y0, y1 + 1):
		for x in range(x0, x1 + 1):
			var d := Vector2(float(x), float(y)).distance_to(c)
			if d < rmin or d > rmax:
				continue
			if pred.call(img.get_pixel(x, y)):
				n += 1
	return n
