{"content":"extends Node

var _sub: SubViewport


func _ready() -> void:
	_sub = SubViewport.new()
	_sub.size = Vector2i(700, 400)
	_sub.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	_sub.transparent_bg = false
	add_child(_sub)
	var bg := ColorRect.new()
	bg.color = Color(0.06, 0.07, 0.10)
	bg.size = Vector2(700, 400)
	_sub.add_child(bg)

	var coin := UI_Manager.ValuePopup.new()
	coin.setup("+120g", "coin", Color(1.0, 0.87, 0.40), 2.0, 34)
	coin.position = Vector2(40, 40)
	_sub.add_child(coin)
	var sword := UI_Manager.ValuePopup.new()
	sword.setup("+300g", "sword", UiKit.C_GOLD, 2.0, 34)
	sword.position = Vector2(40, 160)
	_sub.add_child(sword)
	var cross := UI_Manager.ValuePopup.new()
	cross.setup("+55", "cross", Color(0.50, 1.0, 0.60), 2.0, 26)
	cross.position = Vector2(40, 280)
	_sub.add_child(cross)

	await get_tree().process_frame
	await get_tree().process_frame
	await get_tree().process_frame
	print("SIZES coin=", coin.size, " sword=", sword.size, " cross=", cross.size)

	var img := _sub.get_texture().get_image()
	img.save_png("res://.tmp/shot/popups.png")
	# 金币：图标区内金色像素（金芯亮面）+ 深色外环
	print("COIN_GOLD=", _count(img, Rect2i(40, 40, 64, 60), func(c: Color) -> bool:
		return c.r > 0.85 and c.g > 0.65 and c.g < 0.95 and c.b < 0.55))
	print("SWORD_GOLD=", _count(img, Rect2i(40, 160, 64, 60), func(c: Color) -> bool:
		return c.r > 0.85 and c.g > 0.65 and c.b < 0.55))
	print("CROSS_GREEN=", _count(img, Rect2i(40, 280, 56, 50), func(c: Color) -> bool:
		return c.g > 0.80 and c.r < 0.75 and c.b < 0.85))
	print("TEXT_LIGHT=", _count(img, Rect2i(104, 40, 160, 60), func(c: Color) -> bool:
		return c.r > 0.85 and c.g > 0.70))
	print("POPUP_PX_DONE")
	get_tree().quit(0)


func _count(img: Image, r: Rect2i, pred: Callable) -> int:
	var n := 0
	for y in range(r.position.y, r.position.y + r.size.y):
		for x in range(r.position.x, r.position.x + r.size.x):
			if x < 0 or y < 0 or x >= img.get_width() or y >= img.get_height():
				continue
			if pred.call(img.get_pixel(x, y)):
				n += 1
	return n
","file_path":".tmp\popup_pixel_test.gd"}

