	# —— 自身属性面板（同 host attribute_panel：小地图下方 (40, 350+safe)，标题条 30rs + 图例 26rs + 18 行 2 列 ×28rs）——
	func _draw_attr_panel(s: float) -> void:
		var cfg: Array = UiManager.ATTRIBUTE_ROWS
		var n := mini(cfg.size(), int(sa.size() / 3))
		if n <= 0:
			return
		var pad := 12.0 * s
		var head_h := 30.0 * s
		var legend_h := 26.0 * s
		var row_h := 28.0 * s
		var col_w := 200.0 * s
		var col_gap := 12.0 * s
		var ncol := 2
		var panel_w := pad * 2.0 + col_w * float(ncol) + col_gap * float(ncol - 1)
		var panel_h := pad * 2.0 + head_h + legend_h + row_h * ATTR_ROWS_PER_COL
		# 默认折叠（同 host UiManager.attr_collapsed）：只留一条标题条，点一下展开
		if attr_collapsed:
			panel_w = minf(panel_w, 300.0 * s)
			panel_h = pad * 2.0 + head_h
		# 紧贴小地图下方（小地图 inset 40 + 300，再留 10），顶边固定、向下展开（同 host）
		var left := 40.0 + UiKit.safe_left()
		var top := 40.0 + safe_top + 460.0
		draw_style_box(UiKit.flat(0.5, 12, 1), Rect2(left, top, panel_w, panel_h))
		_attr_head_rect = Rect2(left, top, panel_w, maxf(panel_h, head_h + pad * 2.0))

		if ms <= 0:
			_flash_exp.erase(nid)
			_flash_amt.erase(nid)
			return 0.0
		return clampf(float(ms) / 500.0, 0.0, 1.0)

	# —— 小地图右侧英雄环形头像带（同 host respawn_container：小地图右侧 (340,28)，单元 130×150、行距 6、环 r=56.25）——
	func _draw_respawn_widget_rows() -> void:
		var x0 := 500.0 + UiKit.safe_left()   # 小地图 450 宽 + 内距
		var y0 := 28.0 + safe_top
		var cell_w := 130.0
		var cell_h := 150.0
		var sep_x := 4.0     # host 行内 HBoxContainer 默认 separation
		var sep_y := 6.0     # host respawn_container.separation
		var row1: Array = []
		var row2: Array = []
		for r in widget_rows:
			if r.size() < 10:
				continue
			if int(r[1]) == 0:
				row1.append(r)   # 我方（蓝）整排：含残血/复活读秒，恒显
			else:
				row2.append(r)   # 敌方（红）：host 只在阵亡时下发，复活自动消失
		var rows_all: Array = [row1]
		if not row2.is_empty():
			rows_all.append(row2)
		var yy := y0
		for row in rows_all:
			var xx := x0
			for r in row:
				_draw_widget_cell(r, xx, yy)
				xx += cell_w + sep_x
			yy += cell_h + sep_y

	func _draw_widget_cell(r: Array, xx: float, yy: float) -> void:
		var center := Vector2(xx + 65.0, yy + 75.0)   # 单元 130×150 中心（同 host custom_minimum_size）
		var ring_r := 56.25                            # 同 host ring_radius = 45×1.25
		var team := int(r[1])
		var is_ai := int(r[6]) == 1
		var dead := int(r[7]) == 1
		var bg := Color(1.0, 0.33, 0.264)
		if team == 0:
			bg = Color(0.0, 0.886, 1.0) if is_ai else Color(0.0, 0.886, 0.431)
		if dead:
			bg = Color(0.32, 0.05, 0.07) if team == 1 else Color(0.04, 0.05, 0.07)
		# 专属英雄徽记头像（同 host RespawnWidget；r[2]=英雄名）
		var team_tint := Color(1.0, 0.33, 0.264) if team == 1 else (Color(0.0, 0.886, 1.0) if is_ai else Color(0.0, 0.886, 0.431))
		HeroArt.draw_portrait(self, center, ring_r, str(r[2]), team_tint, dead)
		draw_arc(center, ring_r + 3.75, 0.0, TAU, 48, Color.BLACK, 5.0)
		if dead:
			var total := float(r[9])
			var remain := maxf(float(r[8]), 0.0)
			var prog := 1.0
			if total > 0.0:
				prog = clampf(1.0 - remain / total, 0.0, 1.0)
			draw_arc(center, ring_r + 3.75, -PI / 2.0, -PI / 2.0 + TAU * prog, 48, Color.WHITE, 5.0)
			_draw_widget_mid(center, str(int(ceil(remain))))
		else:
			var maxhp := maxf(float(r[5]), 1.0)
			var hratio := clampf(float(r[4]) / maxhp, 0.0, 1.0)
			var hcol := Color(0.25, 1.0, 0.3) if hratio > 0.5 else (Color(1.0, 0.9, 0.2) if hratio > 0.25 else Color(1.0, 0.3, 0.2))
			draw_arc(center, ring_r + 3.75, -PI / 2.0, -PI / 2.0 + TAU * hratio, 48, hcol, 5.0)

	func _draw_widget_mid(center: Vector2, txt: String) -> void:
		var sz := _font.get_string_size(txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 24).x
		var mp := Vector2(center.x - sz * 0.5, center.y + 9.0)
		draw_string_outline(_font, mp, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 24, 3, Color(0, 0, 0, 0.75))
		draw_string(_font, mp, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, 24, Color.WHITE)

static func terrain_texture(px: int, map_size: float, grid: int = 120) -> ImageTexture:
	var img := Image.create(grid, grid, false, Image.FORMAT_RGBA8)
	for gy in range(grid):
		var wz: float = (float(gy) + 0.5) / float(grid) * map_size - map_size * 0.5
		for gx in range(grid):
			var wx: float = (float(gx) + 0.5) / float(grid) * map_size - map_size * 0.5
			var c := world_color(wx, wz, map_size)
			var edge: float = maxf(absf(wx), absf(wz)) / (map_size * 0.5)
			if edge > 0.82:
				c = c.darkened((edge - 0.82) / 0.18 * 0.45)
			img.set_pixel(gx, gy, c)
	img.resize(px, px, Image.INTERPOLATE_BILINEAR)
	return ImageTexture.create_from_image(img)

# ==================== 防御塔 / 水晶 ====================

## 防御塔四种轮廓：外塔=方形城垛 / 内塔=八边形 / 高地塔=菱形 / 水晶=六边形宝石。
## 血量从底部向上填充，低于 45% 泛红；摧毁画灰叉。
static func draw_turret(ci: CanvasItem, pos: Vector2, ratio: float, col: Color, ttype: String, alive: bool = true) -> void:
	var size: float = 9.0
	if ttype == "inner":
		size = 10.5
	elif ttype == "high":
		size = 11.5
	elif ttype == "crystal":
		size = 15.0
	var h: float = size * 0.5
	var dark := Color(0.045, 0.055, 0.075, 0.97)
	var lit: Color = col.lightened(0.42)
	var shade: Color = col.darkened(0.32)
	match ttype:
		"crystal":
			if alive:
				ci.draw_circle(pos, h + 6.0, Color(col.r, col.g, col.b, 0.14))
				ci.draw_circle(pos, h + 3.0, Color(col.r, col.g, col.b, 0.20))
			var pts := PackedVector2Array()
			for i in range(6):
				var a: float = -PI / 2.0 + TAU * float(i) / 6.0
				pts.append(pos + Vector2(cos(a), sin(a)) * h)
			ci.draw_colored_polygon(pts, dark)
			if alive:
				ci.draw_colored_polygon(PackedVector2Array([pts[5], pts[0], pts[1], pts[2], pos + Vector2(0, h * 0.2)]), lit)
				ci.draw_colored_polygon(PackedVector2Array([pts[2], pts[3], pts[4], pts[5], pos + Vector2(0, h * 0.2)]), shade)
				ci.draw_line(pts[2], pos + Vector2(0, h * 0.8), Color(1, 1, 1, 0.30), 1.2)
				ci.draw_circle(pos + Vector2(-h * 0.24, -h * 0.38), 2.0, Color(1, 1, 1, 0.60))
				ci.draw_arc(pos, h + 3.0, -PI / 2.0, -PI / 2.0 + TAU * clampf(ratio, 0.0, 1.0), 28,
					Color(1.0, 0.42, 0.30) if ratio < 0.45 else Color(0.55, 1.0, 0.72), 2.0)
			ci.draw_polyline(pts + PackedVector2Array([pts[0]]), Color.BLACK, 1.4)
			if not alive:
				_dead_x(ci, pos, h + 1.5)
			return
		"high":
			var d := PackedVector2Array([pos + Vector2(0, -h - 1.5), pos + Vector2(h, 0), pos + Vector2(0, h), pos + Vector2(-h, 0)])
			ci.draw_colored_polygon(d, dark)
			if alive and ratio > 0.0:
				var fh: float = h * 2.0 * clampf(ratio, 0.0, 1.0)
				ci.draw_rect(Rect2(pos.x - h, pos.y + h - fh, h * 2.0, fh), col)

