func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 2.0 and guard < 4000:
		guard += 1
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var mm = bm.get("minimap")
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/hud.png")
	var ct := get_viewport().get_canvas_transform()
	var xf: Transform2D = mm.get_global_transform_with_canvas()
	var p0: Vector2 = ct * xf.origin
	var p1: Vector2 = ct * (xf * Vector2(mm.size.x, mm.size.y))
	print("IMG=", img.get_size(), " MM_IMG_TOPLEFT=", p0, " MM_IMG_BOTRIGHT=", p1, " ct=", ct)
	# 小地图区域 ASCII 采样：亮度分层，便于肉眼判断底板/内容是否错位
	var step := maxi(1, int(round((p1.x - p0.x) / 56.0)))
	var lines: Array = []
	for y in range(int(p0.y) - 12, int(p1.y) + 13, step):
		var row := ""
		for x in range(int(p0.x) - 12, int(p1.x) + 13, step):
			if x < 0 or y < 0 or x >= img.get_width() or y >= img.get_height():
				row += " "
				continue
			var c := img.get_pixel(x, y)
			var l := c.get_luminance()
			if l < 0.04: row += "."
			elif l < 0.12: row += ":"
