	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 2.0 and guard < 4000:
		guard += 1
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/hud2.png")
	print("IMG=", img.get_size())
	_scan_h(img, 265, 20, 530)
	_scan_v(img, 265, 20, 530)
	# 上/下/左/右边界附近细节：逐像素打印 30..52 的颜色
	for x in range(34, 50):
		var c := img.get_pixel(x, 265)
		print("PX x=%d rgb=(%.3f,%.3f,%.3f,%.2f)" % [x, c.r, c.g, c.b, c.a])
	print("EDGE_DONE")
	get_tree().quit(0)


func _scan_h(img: Image, y: int, x0: int, x1: int) -> void:
	var prev := img.get_pixel(x0, y)
	var out: Array = []
	for x in range(x0 + 1, x1):
		var c := img.get_pixel(x, y)
		var d := absf(c.r - prev.r) + absf(c.g - prev.g) + absf(c.b - prev.b)
		if d > 0.12:
			out.append("%d:(%.2f,%.2f,%.2f)" % [x, c.r, c.g, c.b])
		prev = c
	print("HSCAN y=", y, " -> ", out)


func _scan_v(img: Image, x: int, y0: int, y1: int) -> void:
	var prev := img.get_pixel(x, y0)
	var out: Array = []
	for y in range(y0 + 1, y1):
		var c := img.get_pixel(x, y)
		var d := absf(c.r - prev.r) + absf(c.g - prev.g) + absf(c.b - prev.b)
		if d > 0.12:
			out.append("%d:(%.2f,%.2f,%.2f)" % [y, c.r, c.g, c.b])
		prev = c
	print("VSCAN x=", x, " -> ", out)
","file_path":".tmp\hud_shot2.gd"}

