{"content":"extends Node


func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 2.0 and guard < 4000:
		guard += 1
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/hud3.png")
	print("IMG=", img.get_size(), " VPRECT=", get_viewport().get_visible_rect().size)
	# 小地图边框像素：上/左/右/下边界
	for x in range(36, 47):
		var c := img.get_pixel(x, 265)
		print("TOPEDGE x=%d (%.2f,%.2f,%.2f)" % [x, c.r, c.g, c.b])
	for y in range(36, 47):
		var c := img.get_pixel(265, y)
		print("LEFTEDGE y=%d (%.2f,%.2f,%.2f)" % [y, c.r, c.g, c.b])
	for x in range(485, 496):
		var c := img.get_pixel(x, 265)
		print("RIGHTEDGE x=%d (%.2f,%.2f,%.2f)" % [x, c.r, c.g, c.b])
	for y in range(485, 496):
		var c := img.get_pixel(265, y)
		print("BOTEDGE y=%d (%.2f,%.2f,%.2f)" % [y, c.r, c.g, c.b])
	print("EDGE_DONE")
	get_tree().quit(0)
","file_path":".tmp\hud_shot3.gd"}

