for ($y = 0; $y -lt 1080; $y += 27) {
  $line = ""
  for ($x = 0; $x -lt 2400; $x += 20) {
    $c = $bmp.GetPixel($x, $y)
    $l = (0.299 * $c.R + 0.587 * $c.G + 0.114 * $c.B) / 255.0
    if ($l -lt 0.05) { $line += "." }
    elseif ($l -lt 0.12) { $line += ":" }
