    elseif ($l -lt 0.38) { $line += "=" }
    elseif ($l -lt 0.6) { $line += "*" }
    else { $line += "#" }
  }
  $rows += ("R{0:D2} {1}" -f [int]($y / 27), $line)
}
$rows | ForEach-Object { $_ }
$bmp.Dispose()","description":"Coarse ASCII of user screenshot"}

