{"command":"Add-Type -AssemblyName System.Drawing
$bmp = New-Object System.Drawing.Bitmap ((Resolve-Path ".tmp\user_shots\微信图片_20261031114500_399_195.jpg").Path)
$minX = 99999; $maxX = -1; $minY = 99999; $maxY = -1
$pts = @()
for ($y = 0; $y -lt 700; $y += 1) {
  for ($x = 0; $x -lt 700; $x += 1) {
    $c = $bmp.GetPixel($x, $y)
    if ($c.R -gt 195 -and $c.G -gt 160 -and $c.G -lt 225 -and $c.B -lt 130) {
      $pts += "$x,$y"
      if ($x -lt $minX) { $minX = $x }; if ($x -gt $maxX) { $maxX = $x }
      if ($y -lt $minY) { $minY = $y }; if ($y -gt $maxY) { $maxY = $y }
    }
  }
}
"gold_pixels=$($pts.Count) bbox=($minX,$minY)-($maxX,$maxY)"
"sample: " + (($pts | Select-Object -First 12) -join " | ")
$bmp.Dispose()","description":"Detect gold corner brackets in user screenshot"}

