script = ExtResource("1_netcl")
--- NetSession cli parse ---

# ---------- 参数解析 ----------

func _parse_args() -> void:
	var args: PackedStringArray = OS.get_cmdline_user_args()
	var i := 0
	while i < args.size():
		var a: String = args[i]
		if a == "--net-host":
			mode = Mode.HOST
			cli_mode = true
			phase = Phase.BATTLE
			if i + 1 < args.size() and args[i + 1].is_valid_int():
				host_port = args[i + 1].to_int()
				i += 1
		elif a == "--net-join":
			mode = Mode.CLIENT
			cli_mode = true
			if i + 1 < args.size() and ":" in args[i + 1]:
				var parts: PackedStringArray = args[i + 1].split(":")
				join_address = parts[0]
				if parts[1].is_valid_int():
					host_port = parts[1].to_int()
				i += 1
		elif a == "--net-test":
			net_test = true
		i += 1


# ---------- 连接建立 ----------

func _setup_peer() -> void:
	var is_web := OS.has_feature("web")
	match mode:
		Mode.HOST:
			if is_web:
				# 浏览器内无法监听 UDP/WS 端口：网页版只能当客户端，房间由桌面主机开
				printerr("[Net] 网页版不支持创建房间，请用桌面版当主机")
				mode = Mode.NONE
				return
			var peer := ENetMultiplayerPeer.new()

