	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 2.0 and guard < 4000:
		guard += 1
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/corner.png")
	var mm = bm.get("minimap")
	var origin: Vector2 = mm.global_position
	print("MM_ORIGIN=", origin, " SIZE=", mm.size)
	# 四角各 26×26：G=金色角标 D=深色底板 L=高光线 t=地图内容
	for corner in [Vector2i(0, 0), Vector2i(1, 0), Vector2i(0, 1), Vector2i(1, 1)]:
		print("CORNER ", corner)
		for dy in range(0, 26):
			var row := ""
			for dx in range(0, 26):
				var lx: float = dx if corner.x == 0 else mm.size.x - 26 + dx
				var ly: float = dy if corner.y == 0 else mm.size.y - 26 + dy
				var c := img.get_pixel(int(origin.x + lx), int(origin.y + ly))
				var lum := c.get_luminance()
				if c.r > 0.55 and c.g > 0.4 and c.b < 0.42:
					row += "G"
				elif lum < 0.10:
					row += "D"
				elif c.b > c.r + 0.12 and lum > 0.22:
					row += "L"
				else:
					row += "t"
			print("R%02d %s" % [dy, row])
	print("CORNER_DONE")
	get_tree().quit(0)
