		guard += 1
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/attrbar.png")
	# 属性条那一行的左右边界：扫 y=522，报出与大背景差异明显的列
	var y := 522
	var prev := img.get_pixel(20, y)
	var out: Array = []
	for x in range(21, 520):
		var c := img.get_pixel(x, y)
		var d := absf(c.r - prev.r) + absf(c.g - prev.g) + absf(c.b - prev.b)
		if d > 0.10:
			out.append("%d:(%.2f,%.2f,%.2f)" % [x, c.r, c.g, c.b])
		prev = c
	print("BAR_SCAN y=", y, " -> ", out)
	# 小地图右上角与属性条右缘对比
	print("MM_RIGHT=490 ATTR_RIGHT_EXPECT=490")
	print("ATTRBAR_DONE")
	get_tree().quit(0)
