content.arguments:
{"command":"Add-Type -AssemblyName System.Drawing
$bmp = New-Object System.Drawing.Bitmap ((Resolve-Path "我的截图\小地图底板错位.png").Path)
$ox = 15; $oy = 141
function Cls($c) {
  $r = $c.R/255.0; $g = $c.G/255.0; $b = $c.B/255.0; $lum = 0.299*$r + 0.587*$g + 0.114*$b
  if ($r -gt 0.5 -and $g -gt 0.35 -and $b -lt 0.35 -and $r -gt $b + 0.25) { return "G" }   # 金色
  if ($b -gt $r + 0.12 -and $lum -gt 0.2) { return "L" }                                  # 冷光高光
  if ($lum -lt 0.09) { return "D" }                                                       # 深色底板
  return "t"
}
function ScanRow($cy, $x0, $x1) {
  $prev = $null; $out = @()
  for ($cx = $x0; $cx -le $x1; $cx++) {
    $c = $bmp.GetPixel($ox + $cx, $oy + $cy); $k = Cls $c
    if ($k -ne $prev) { $out += "$cx$k"; $prev = $k }
  }
  "$out"
}
function ScanCol($cx, $y0, $y1) {
  $prev = $null; $out = @()
  for ($cy = $y0; $cy -le $y1; $cy++) {
    $c = $bmp.GetPixel($ox + $cx, $oy + $cy); $k = Cls $c
