{"content":"import sys
from PIL import Image

path = r"C:\Users\18749\Documents\honor-king\我的截图\小地图底板错位.png"
im = Image.open(path).convert("RGB")
W, H = im.size
print("SIZE", W, H)
px = im.load()
OX, OY = 15, 141

def cls(c):
    r, g, b = c[0] / 255, c[1] / 255, c[2] / 255
    lum = 0.299 * r + 0.587 * g + 0.114 * b
    if r > 0.5 and g > 0.35 and b < 0.35 and r > b + 0.25:
        return "G"
    if b > r + 0.12 and lum > 0.20:
        return "L"
    if lum < 0.09:
        return "D"
    return "t"

def runs_row(cy, x0, x1):
    out = []
    prev = None
    for cx in range(x0, x1 + 1):
        k = cls(px[OX + cx, OY + cy])
        if k != prev:
            out.append(f"{cx}{k}")
            prev = k
    return " ".join(out)

def runs_col(cx, y0, y1):
    out = []
    prev = None
    for cy in range(y0, y1 + 1):
        k = cls(px[OX + cx, OY + cy])
        if k != prev:
            out.append(f"{cy}{k}")
            prev = k
    return " ".join(out)

print("ROW y=200:", runs_row(200, 20, 560))
print("COL x=250:", runs_col(250, 20, 620))
print("ROW y=520:", runs_row(520, 20, 560))
print("COL x=60 :", runs_col(60, 20, 700))
print("ROW y=60 (顶部带):", runs_row(60, 1100, 1800))
print("ROW y=100 (头像带):", runs_row(100, 440, 1300))
","file_path":".tmp\analyze_user_shot.py"}

