{"content":"import numpy as np
from PIL import Image

src = r"C:\Users\18749\Documents\honor-king\我的截图\小地图底板错位.png"
im = Image.open(src).convert("RGB")
a = np.asarray(im).astype(np.int16)
OX, OY = 15, 141
sub = a[OY:OY + 1400, OX:OX + 2400]          # 画布坐标
H, W, _ = sub.shape

def long_runs(axis, minlen=90, tol=6):
    """找同色长直线段（面板描边）：axis=0 横线(按行)，axis=1 竖线(按列)"""
    out = []
    if axis == 0:
        for y in range(H):
            row = sub[y]
            start = 0
            for x in range(1, W):
                if np.abs(row[x] - row[start]).max() > tol:
                    if x - start >= minlen:
                        out.append((y, start, x - 1, tuple(int(v) for v in row[start])))
                    start = x
            if W - start >= minlen:
                out.append((y, start, W - 1, tuple(int(v) for v in row[start])))
    else:
        for x in range(W):
            col = sub[:, x]
            start = 0
            for y in range(1, H):
                if np.abs(col[y] - col[start]).max() > tol:
                    if y - start >= minlen:
                        out.append((x, start, y - 1, tuple(int(v) for v in col[start])))
                    start = y
            if H - start >= minlen:
                out.append((x, start, H - 1, tuple(int(v) for v in col[start])))
    return out

print("== 横描边（y: x0..x1  颜色）==")
for y, x0, x1, c in long_runs(0, 120):
    if x0 < 1400 and y < 1000:
        print(f"y={y:4d} x={x0:4d}..{x1:4d} len={x1-x0+1:4d} rgb={c}")
print("== 竖描边（x: y0..y1  颜色）==")
for x, y0, y1, c in long_runs(1, 120):
    if x < 1400 and y0 < 1000:
        print(f"x={x:4d} y={y0:4d}..{y1:4d} len={y1-y0+1:4d} rgb={c}")
","file_path":".tmp\find_borders.py"}

