{"content":"from PIL import Image

src = r"C:\Users\18749\Documents\honor-king\我的截图\小地图底板错位.png"
im = Image.open(src).convert("RGB")
px = im.load()
OX, OY = 15, 141

def ch(c):
    r, g, b = c[0] / 255, c[1] / 255, c[2] / 255
    lum = 0.299 * r + 0.587 * g + 0.114 * b
    if r > 0.5 and g > 0.35 and b < 0.35 and r > b + 0.25:
        return "@"      # 金
    if b > r + 0.12 and lum > 0.55:
        return "L"      # 亮冷光描边
    if b > r + 0.12 and lum > 0.18:
        return "l"      # 淡蓝
    if g > r + 0.15 and b > r + 0.15:
        return "w"      # 青蓝（水）
    if g > r + 0.04 and g > b - 0.02 and lum > 0.22:
        return "g"      # 草绿
    if lum > 0.6:
        return "#"      # 很亮
    if lum < 0.08:
        return "D"      # 极暗（深色底板/夜空）
    if lum < 0.18:
        return "d"
    return "."

step = 10
x0, x1, y0, y1 = 0, 1000, 0, 1000
print("     " + "".join(str((x // 100) % 10) for x in range(x0, x1, step)))
for y in range(y0, y1, step):
    line = "".join(ch(px[OX + x, OY + y]) for x in range(x0, x1, step))
    print(f"{y:4d} {line}")
","file_path":".tmp\ascii_shot.py"}

