{"content":"extends Node


func ch(c: Color) -> String:
	var lum := c.get_luminance()
	if c.r > 0.55 and c.g > 0.30 and c.b > 0.35 and c.r > c.g + 0.25:
		return "P"
	if c.r > 0.5 and c.g > 0.35 and c.b < 0.35 and c.r > c.b + 0.25:
		return "@"
	if c.b > c.r + 0.12 and lum > 0.5:
		return "L"
	if c.b > c.r + 0.10 and lum > 0.17:
		return "l"
	if c.g > c.r + 0.15 and c.b > c.r + 0.15:
		return "w"
	if c.g > c.r + 0.04 and lum > 0.22:
		return "g"
	if lum > 0.55:
		return "#"
	if lum < 0.06:
		return "D"
	if lum < 0.14:
		return "d"
	return "."


func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while float(bm.get("game_time")) < 2.0 and guard < 4000:
		guard += 1
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/cur_full.png")
	var step := 20
	for y in range(0, 1000, step):
		var line := ""
		for x in range(0, 1400, step):
			line += ch(img.get_pixel(x, y))
		print(f"{y:4d} {line}")
	print("DONE")
	get_tree().quit(0)
","file_path":".tmp\cur_ascii.gd"}

