var tex: ImageTexture


func _make_tex() -> ImageTexture:
	var img := Image.create(450, 450, false, Image.FORMAT_RGBA8)
	for y in range(450):
		for x in range(450):
			var c := Color(0.1, 0.1, 0.1)
			if x < 225 and y < 225:
				c = Color(1, 0, 0)      # 左上 红
			elif x >= 225 and y < 225:
				c = Color(0, 1, 0)      # 右上 绿
			elif x < 225:
				c = Color(0, 0, 1)      # 左下 蓝
			else:
				c = Color(1, 1, 1)      # 右下 白
			img.set_pixel(x, y, c)
	return ImageTexture.create_from_image(img)


func _ready() -> void:
	tex = _make_tex()
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/negrect.png")
	# 采样：负尺寸 rect 起笔在 (450,450)
	print("A 内 (100,100)  ", img.get_pixel(100, 100))
	print("A 内 (300,300)  ", img.get_pixel(300, 300))
	print("B 外 (600,600)  ", img.get_pixel(600, 600))
	print("B 外 (860,860)  ", img.get_pixel(860, 860))
	print("B 外 (600,860)  ", img.get_pixel(600, 860))
