```gdscript
# 挑选回城塔：离敌人足够远、离自己最近；敌人贴脸时返回 null（改为躲远）
func _pick_recall_turret() -> Turret:
	var tree := hero.get_tree()
	if tree == null:
		return null
	var best: Turret = null
	var best_d := AiConfig.FRIENDLY_TURRET_FAR + 1.0
	for entity in tree.get_nodes_in_group("turrets"):
		if not is_instance_valid(entity) or not (entity is Turret):
			continue
		var t := entity as Turret
		if t.health <= 0.0 or t.team != hero.team:
			continue
		var d: float = hero.global_position.distance_to(t.global_position)
		if d > AiConfig.FRIENDLY_TURRET_FAR or d >= best_d:
			continue
		if _recall_spot_threatened(t.global_position):
			continue
		best_d = d
		best = t
	return best

# 回城点周围有没有敌方英雄（读条 7 秒，够对面走近）
func _recall_spot_threatened(pos: Vector3) -> bool:
	var tree := hero.get_tree()
	if tree == null:
		return false
	for e in tree.get_nodes_in_group("entities"):
		if not is_instance_valid(e) or not (e is Hero):
			continue
		var h := e as Hero
		if h.team == hero.team or h.health <= 0.0 or not h.visible:
			continue
		if h.global_position.distance_to(pos) <= AiConfig.RECALL_SPOT_CLEAR:
			return true
	return false
```

