func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 0.5:
			break

	var ai_hero: Hero = null
	var ai_node: HeroAI = null
	var foe: Hero = null
	for n in get_tree().get_nodes_in_group("heroes"):
		var h := n as Hero
		if h == null:
			continue
		if h.is_ai and ai_node == null:
			ai_hero = h
			for c in h.get_children():
				if c is HeroAI:
					ai_node = c
		elif not h.is_ai:
			foe = h
	print("AI=", ai_hero.display_name if ai_hero else "none", " foe=", foe.display_name if foe else "none")
	if ai_hero == null or ai_node == null or foe == null:
		get_tree().quit(1)
		return

	# 把敌人挪远：AI 应能在己方塔旁边起手回城
	foe.global_position = Vector3(0, 0, 0) + Vector3(0, 0, -30)
	ai_hero.health = ai_hero.actual_max_health * 0.2
	var spot := ai_node._find_safe_recall_spot()
	print("SAFE_SPOT=", spot)
	if spot != Vector3.ZERO:
		ai_hero.global_position = spot
		for i in range(3):
			ai_node._recall_safe_behavior(0.5)
			await get_tree().process_frame
		print("RECALLING_FAR=", ai_hero.is_recalling)

	# 敌人贴到正在回城的 AI 身边：应取消回城，并换到别的点
	foe.global_position = ai_hero.global_position + Vector3(2, 0, 0)
	ai_node._recall_safe_behavior(0.5)
	await get_tree().process_frame
	print("RECALLING_AFTER_THREAT=", ai_hero.is_recalling)
	var spot2 := ai_node._find_safe_recall_spot()
	print("SPOT2=", spot2, " MOVED_AWAY=", ai_hero.move_target.distance_to(ai_hero.global_position) > 1.0)
	get_tree().quit(0)
","file_path":".tmp\recall_probe.gd"}

