```gdscript
static func _build_flower_mesh(rng: RandomNumberGenerator) -> ArrayMesh:
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var palette := [Color(0.95,0.62,0.78), Color(0.96,0.94,0.86), Color(0.85,0.72,0.98), Color(0.99,0.86,0.42)]
	for i in range(7):
		var a: float = rng.randf_range(0.0, TAU)
		var d: float = sqrt(rng.randf()) * 0.58
		var y: float = rng.randf_range(0.55, 1.15)
		var c := Vector3(cos(a) * d, y, sin(a) * d)
		var col: Color = palette[i % palette.size()]
		var size := rng.randf_range(0.11, 0.17)
		# 花瓣：两片交叉微倾
		_add_flat_quad(st, c, size, rng.randf_range(0.0, TAU), rng.randf_range(-0.25, 0.25), col)
		_add_flat_quad(st, c + Vector3(0, 0.02, 0), size * 0.62, rng.randf_range(0.0, TAU), rng.randf_range(-0.3, 0.3), Color(0.99, 0.90, 0.45))
	return st.commit()
```
`_add_flat_quad(st, center, size, rot_y, tilt, col)`:
```gdscript
static func _add_flat_quad(st: SurfaceTool, c: Vector3, size: float, rot_y: float, tilt: float, col: Color) -> void:
	var basis := Basis(Vector3.UP, rot_y) * Basis(Vector3.RIGHT, tilt)
	var n := (basis * Vector3.UP).normalized()
	var h := size * 0.5
	var corners := [Vector3(-h, 0, -h), Vector3(h, 0, -h), Vector3(h, 0, h), Vector3(-h, 0, h)]
	for idx in [0, 1, 2, 0, 2, 3]:
		var v: Vector3 = basis * corners[idx] + c
		st.set_color(col)
		st.set_normal(n)
		st.set_uv(Vector2(0.5, 0.5))
		st.add_vertex(v)
```

