{"content":"extends Node


func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 1.0:
			break
	var walls := get_tree().get_nodes_in_group("walls")
	var thick_count := {}
	var decor := 0
	for w in walls:
		var t: float = snappedf(float(w.get("thick")), 0.01)
		thick_count[t] = int(thick_count.get(t, 0)) + 1
		for c in w.get_children():
			if c.name == "WallDecor":
				decor += 1
	var bushes := get_tree().get_nodes_in_group("bush")
	var flowers := 0
	for b in bushes:
		for c in b.get_children():
			if c.name == "BushFlowers":
				flowers += 1
	var turrets := get_tree().get_nodes_in_group("turrets")
	var paves := 0
	for t in turrets:
		for c in t.get_children():
			if c.name == "TurretPave":
				paves += 1
	print("WALLS=", walls.size(), " THICK=", thick_count, " WALL_DECOR=", decor)
	print("BUSHES=", bushes.size(), " FLOWERS=", flowers)
	print("TURRETS=", turrets.size(), " PAVES=", paves)
	print("DONE")
	get_tree().quit(0)
","file_path":".tmp\decor_probe.gd"}

