func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 1.0:
			break
	var arenas := 0
	for c in bm.get_children():
		if c.name == "LaneArena":
			arenas += 1
	print("ARENAS=", arenas)
	# 站到发育路兵线交汇处，拍一张看擂台
	var hero: Hero = bm.get("hero")
	hero.global_position = Vector3(43, 0, 43)
	for i in range(40):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/arena_ingame.png")
	print("SHOT ", img.get_width(), "x", img.get_height())
	get_tree().quit(0)
","file_path":".tmp\arena_probe.gd"}

