import numpy as np

im = Image.open(r"C:\Users\18749\Documents\honor-king\.tmp\shot\arena_ingame.png").convert("RGB")
a = np.asarray(im).astype(np.float32)
h, w, _ = a.shape
print("size", w, h, "mean", a.mean(axis=(0, 1)).round(1))

# 屏幕中心一块（擂台应在英雄脚下）
cy, cx = int(h * 0.62), w // 2
crop = a[cy - 260:cy + 260, cx - 260:cx + 260]
print("center crop mean", crop.mean(axis=(0, 1)).round(1), "std", crop.std(axis=(0, 1)).round(1))

def ch(c):
    r, g, b = c
    if r > 120 and r > g + 25 and b > 90:
        return "P"
    if g > r + 18 and g > b + 18:
        return "G"
    if b > r + 22:
        return "b"
    if abs(r - g) < 16 and abs(g - b) < 16:
        return "." if r < 90 else ("o" if r < 160 else "#")
    return "?"

step = 14
for y in range(cy - 280, cy + 288, step):
    print("%4d " % y + "".join(ch(a[y, x]) for x in range(cx - 300, cx + 300, step)))
","file_path":".tmp\check_arena.py"}

