var _shot_idx := 0


func _capture(name: String) -> void:
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/%s.png" % name)
	print("SHOT ", name)


func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 1.0:
			break
	var hero: Hero = bm.get("hero")
	hero.global_position = Vector3(43, 0, 43)
	for i in range(40):
		await get_tree().process_frame
	for h in get_tree().get_nodes_in_group("heroes"):
		h.visible = false
	for m in get_tree().get_nodes_in_group("minions"):
		m.visible = false

	# 收集擂台 / 塔铺装节点
	var arenas: Array = []
	var paves: Array = []
	for c in bm.get_children():
		if str(c.name).findn("Arena") >= 0:
			arenas.append(c)
	for t in get_tree().get_nodes_in_group("turrets"):
		for c in t.get_children():
			if str(c.name).begins_with("TurretPave"):
				paves.append(c)
	print("ARENA_NODES=", arenas, " PAVE_NODES=", paves.size())

	await _capture("arena_on")
	for a in arenas:
		a.visible = false
	await _capture("arena_off")
	for a in arenas:
		a.visible = true
	for p in paves:
		p.visible = false
	var cam: Camera3D = bm.get("cam")
	var turret_pos := Vector3(28, 0, 58)
	var near_hero: Hero = null
	print("TURRET_SCREEN=", cam.unproject_position(turret_pos))
	await _capture("pave_off")
	get_tree().quit(0)
","file_path":".tmp\diff_probe.gd"}

