{"content":"extends Node


func _capture(name: String) -> void:
	await get_tree().process_frame
	await RenderingServer.frame_post_draw
	var img := get_viewport().get_texture().get_image()
	img.save_png("res://.tmp/shot/%s.png" % name)


func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 1.0:
			break
	var hero: Hero = bm.get("hero")
	hero.global_position = Vector3(43, 0, 43)
	for i in range(45):
		await get_tree().process_frame
	Engine.time_scale = 0.0     # 冻结动画（水面/草摆动），让两张截图只差擂台可见性
	await get_tree().process_frame

	var arenas: Array = []
	for cn in bm.get_children():
		if str(cn.name).begins_with("LaneArena"):
			arenas.append(cn)
	var paves: Array = []
	for t in get_tree().get_nodes_in_group("turrets"):
		for ch2 in t.get_children():
			if str(ch2.name).begins_with("TurretPave"):
				paves.append(ch2)
	var cam := get_viewport().get_camera_3d()
	print("ARENAS=", arenas.size(), " PAVES=", paves.size(), " CAM=", cam.global_position)
	print("ARENA0_SCREEN=", cam.unproject_position(Vector3(43, 0.2, 43)))
	print("PAVE_TURRET_SCREEN=", cam.unproject_position(Vector3(28, 0.2, 58)))

	await _capture("on_all")
	for a in arenas:
		a.visible = false
	await _capture("off_arena")
	for a in arenas:
		a.visible = true
	for p in paves:
		p.visible = false
	await _capture("off_pave")
	get_tree().quit(0)
","file_path":".tmp\diff_probe.gd"}

