# 塔外周青砖铺装（水晶更大一圈）：贴地薄圆盘 + 砖纹 shader，先铺再盖接地暗影
var pave_r: float = 5.8 if display_name == "crystal" else 4.7
var pave := DecorMesh.pave_visual(pave_r)
