	var col: Color = Color(1.0, 0.16, 0.12) if is_hq else Color(1.0, 0.82, 0.12)
	col.a = alpha
	draw_circle(pos, r, Color(col.r, col.g, col.b, alpha * 0.15))  # 淡色内填充，弱化遮挡","old_string":"# 扫描我方塔：正在被攻击（塔的 under_attack_timer > 0）且距上次警告≥10s → 触发一次警告
