{"content":"extends Node


func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 0.6:
			break
	var mm = bm.get("minimap")
	var player_team: int = Config.player_team
	var hq_count := 0
	var outer_count := 0
	for t in bm.get("turrets"):
		if t.team != player_team:
			continue
		var tier := str(t.tower_type)
		if tier == "high" or tier == "crystal":
			t.under_attack_timer = 1.0
			hq_count += 1
		elif tier == "outer" and outer_count == 0:
			t.under_attack_timer = 1.0
			outer_count += 1
	mm._tower_ping_time.clear()
	mm._active_pings.clear()
	mm._scan_tower_warnings()
	print("HQ_TOWERS=", hq_count, " PINGS=", mm._active_pings.size())
	var hq_flags := 0
	for k in mm._active_pings:
		if bool(mm._active_pings[k].get("hq", false)):
			hq_flags += 1
	print("HQ_PINGS=", hq_flags)
	print("FONT_450=", MinimapDraw.countdown_font(450.0), " FONT_200=", MinimapDraw.countdown_font(200.0))
	print("DUR_HQ=", mm.PING_DURATION_HQ, " DUR=", mm.PING_DURATION)
	# 跑一段，让警告圈真的画出来 + 走完过期逻辑
	for i in range(30):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	get_viewport().get_texture().get_image().save_png("res://.tmp/shot/minimap_ping.png")
	print("PINGS_LEFT=", mm._active_pings.size())
	get_tree().quit(0)
","file_path":".tmp\ping_probe.gd"}

