func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 0.8:
			break
	# 路缘统计
	var curbs := 0
	var near_arena := 0
	var spots := [Vector3(43, 0, 43), Vector3(0, 0, 0), Vector3(-43, 0, -43)]
	for plane in bm.get_children():
		if not (plane is MeshInstance3D):
			continue
		for ch2 in plane.get_children():
			if not (ch2 is MeshInstance3D):
				continue
			var mesh := (ch2 as MeshInstance3D).mesh
			if not (mesh is BoxMesh) or absf((mesh as BoxMesh).size.y - 0.22) > 0.001:
				continue
			curbs += 1
			var g: Vector3 = ch2.global_position
			for s in spots:
				if Vector2(g.x - s.x, g.z - s.z).length() < 7.2 + 9.0:
					near_arena += 1
					break
	print("CURBS=", curbs, " NEAR_ARENA=", near_arena)
	# 高地材质
	for c in bm.get_children():
		if c is CSGPolygon3D:
			var mat = c.material_override
			print("FAN_MAT=", mat.get_class(), " ", (mat as ShaderMaterial).get_shader_parameter("ring_w") if mat is ShaderMaterial else 0.0,
				" center=", (mat as ShaderMaterial).get_shader_parameter("arena_center") if mat is ShaderMaterial else Vector2.ZERO)
	# 站到水晶旁拍一张，看高地砖 + 接壤处
	var hero: Hero = bm.get("hero")
	hero.global_position = Vector3(-53, 0, 45)
	for i in range(45):
		await get_tree().process_frame
	await RenderingServer.frame_post_draw
	get_viewport().get_texture().get_image().save_png("res://.tmp/shot/hq_brick.png")
	print("SHOT")
	get_tree().quit(0)
","file_path":".tmp\hq_probe.gd"}

