func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 0.5:
			break
	var crystal = null
	for t in bm.turrets:
		if t.team == Config.player_team and str(t.display_name) == "crystal":
			crystal = t
	print("CRYSTAL_FOUND=", crystal != null)
	bm.crystal_destroyed(Config.Team.PLAYER)
	print("SEQ_ON=", bm._defeat_seq_on, " WINNER=", bm.winner, " PAUSED_NOW=", get_tree().paused)
	var frames := 0
	var banner_frame := -1
	var panel_frame := -1
	while frames < 720:
		frames += 1
		await get_tree().process_frame
		if banner_frame < 0:
			for c in bm.ui.get_children():
				if c is DefeatBanner:
					banner_frame = frames
					break
		if banner_frame >= 0 and panel_frame < 0:
			for c in bm.get_children():
				if c is ResultsPanel:
					panel_frame = frames
					break
		if panel_frame >= 0:
			break
	print("BANNER_FRAME=", banner_frame, " PANEL_FRAME=", panel_frame, " PAUSED=", get_tree().paused)
	get_tree().quit(0)
