func _ready() -> void:
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 0.6:
			break
	bm.crystal_destroyed(Config.player_team)
	var t0 := Time.get_ticks_msec()
	var shot1 := false
	var shot2 := false
	while true:
		await get_tree().process_frame
		var el := Time.get_ticks_msec() - t0
		if not shot1 and el > 2200:
			shot1 = true
			await RenderingServer.frame_post_draw
			get_viewport().get_texture().get_image().save_png("res://.tmp/shot/defeat_fx.png")
			print("SHOT_FX")
