			shot2 = true
			await RenderingServer.frame_post_draw
			get_viewport().get_texture().get_image().save_png("res://.tmp/shot/defeat_banner.png")
			print("SHOT_BANNER")
		if el > 6600:
			break
	print("DONE")
	get_tree().quit(0)
