{"content":"extends Node


func _ready() -> void:
	var win_mode: bool = OS.get_environment("PROBE_WIN") == "1"
	var battle: Node = load("res://scenes/battle.tscn").instantiate()
	add_child(battle)
	await get_tree().process_frame
	await get_tree().process_frame
	var bm = get_tree().get_first_node_in_group("battle_manager")
	bm._start_game_body("亚瑟", "flash")
	var guard := 0
	while guard < 3000:
		guard += 1
		await get_tree().process_frame
		if float(bm.get("game_time")) > 0.6:
			break
	var crystal_team: int = (1 - Config.player_team) if win_mode else Config.player_team
	bm.crystal_destroyed(crystal_team)
	print("WIN_MODE=", win_mode, " SEQ=", bm._end_seq_on, " WINNER_IS_ME=", bm.winner == Config.player_team)
	var frames := 0
	var banner_seen := false
	var banner_won := "?"
	var panel_seen := false
	var banner_at := -1
	var panel_at := -1
	while frames < 720:
		frames += 1
		await get_tree().process_frame
		if not banner_seen:
			for c in bm.ui.get_children():
				if str(c.name) == "EndBanner":
					banner_seen = true
					banner_at = frames
					banner_won = str(c.get("won"))
					break
		if banner_seen and not panel_seen:
			for c in bm.get_children():
				if c is ResultsPanel:
					panel_seen = true
					panel_at = frames
					break
		if panel_seen:
			break
	print("BANNER_AT=", banner_at, " BANNER_WON=", banner_won, " PANEL_AT=", panel_at, " PAUSED=", get_tree().paused)
	get_tree().quit(0)
","file_path":".tmp\end_probe.gd"}

