content.arguments:
{"command":"$ps = @'
try {
  Add-Type -AssemblyName System.Speech
  $list = [System.Speech.Recognition.SpeechRecognitionEngine]::InstalledRecognizers()
  $ri = $list | Where-Object { $_.Culture.Name -eq 'zh-CN' } | Select-Object -First 1
  if ($ri -eq $null) { $ri = $list | Where-Object { $_.Culture.Name -like 'zh*' } | Select-Object -First 1 }
  if ($ri -eq $null) { Write-Output 'ERR:no zh recognizer'; return }
  Write-Output ('PICK:' + $ri.Culture.Name + '|' + $ri.Id)
  $r = New-Object System.Speech.Recognition.SpeechRecognitionEngine($ri.Id)
  $r.SetInputToDefaultAudioDevice()
  $r.LoadGrammar((New-Object System.Speech.Recognition.DictationGrammar))
  $res = $r.Recognize([TimeSpan]::FromSeconds(3))
  if ($res -ne $null) { Write-Output ('TEXT:' + $res.Text.Trim()) } else { Write-Output 'EMPTY' }
} catch { Write-Output ('ERR:' + $_.Exception.Message) }
'@
$out = & powershell.exe -NoProfile -ExecutionPolicy Bypass -Command $ps 2>&1
$out | ForEach-Object { "$_" }","description":"Test explicit recognizer selection","timeoutMs":120000}

