{"command":"$srv = @'
$l = [System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback, 8791)
$l.Start()
"LISTENING"
while ($true) {
  $c = $l.AcceptTcpClient()
  $s = $c.GetStream()
  $ms = New-Object System.IO.MemoryStream
  $buf = New-Object byte[] 4096
  $s.ReadTimeout = 2000
  try {
    while ($true) {
      $n = $s.Read($buf, 0, $buf.Length)
      if ($n -le 0) { break }
      $ms.Write($buf, 0, $n)
      $txt = [Text.Encoding]::UTF8.GetString($ms.ToArray())
      if ($txt -match '\r\n\r\n') {
        $head, $rest = $txt -split '\r\n\r\n', 2
        if ($head -match 'Content-Length: (\d+)') {
          if ($rest.Length -ge [int]$Matches[1]) { break }
        } else { break }
      }
    }
  } catch {}
  $req = [Text.Encoding]::UTF8.GetString($ms.ToArray())
  Add-Content -Path .tmp\llm_req.log -Value ("---REQ---`n" + $req)
  $body = '{"id":"x","choices":[{"index":0,"message":{"role":"assistant","content":"收到，我这就过去支援"}}]}'
  $bytes = [Text.Encoding]::UTF8.GetBytes($body)
  $hdr = "HTTP/1.1 200 OK`r`nContent-Type: application/json`r`nContent-Length: $($bytes.Length)`r`nConnection: close`r`n`r`n"
  $hb = [Text.Encoding]::UTF8.GetBytes($hdr)
  $s.Write($hb, 0, $hb.Length); $s.Write($bytes, 0, $bytes.Length); $s.Flush()
  $c.Close()
}
'@
Set-Content .tmp\llm_mock.ps1 -Value $srv -Encoding UTF8
Remove-Item .tmp\llm_req.log -ErrorAction SilentlyContinue
Start-Process -FilePath pwsh -ArgumentList '-NoProfile','-File','.tmp\llm_mock.ps1' -WorkingDirectory (Get-Location) -WindowStyle Hidden
Start-Sleep -Seconds 2
Test-NetConnection -ComputerName 127.0.0.1 -Port 8791 -InformationLevel Quiet","description":"Start mock LLM server","timeoutMs":120000}

