func _clean(raw: String) -> String:
	var s := raw.strip_edges()
	s = s.replace("\r", " ").replace("\n", " ")
	# 去掉模型爱加的引号
	for q in ["\"", "“", "”", "'", "「", "」"]:
		s = s.replace(q, "")
	# 去掉「名字：」这类前缀（模型常把说话人写进来）
	var ci := s.find("：")
	if ci < 0:
		ci = s.find(":")
	if ci > 0 and ci <= 8:
		s = s.substr(ci + 1)
	if s.length() > 26:
		s = s.substr(0, 26)
	return s.strip_edges()

