		await get_tree().process_frame
	var stage = lobby.find_child("MenuStage", true, false)
	var map = lobby.find_child("TacticalMap", true, false)
	print("STAGE=", stage != null, " MAP=", map != null)
	print("VP=", get_viewport().get_visible_rect().size)
	if map != null:
		print("MAP_RECT=", map.get_global_rect())
		var hits: Array = []
		for key in map.HOTSPOTS:
			var p: Vector2 = map.call("_pt", map.HOTSPOTS[key])
			hits.append("%s->%s" % [key, map.call("_hit", p)])
		print("HOTSPOTS=", hits)
		var r: float = map.call("_hs_radius")
		print("HS_R=", r, " map_size=", map.size)
		print("LANE_NOW=", map.get("lane"))
		lobby.call("_select_lane", "中路")
		for i in 2:
			await get_tree().process_frame
		print("AFTER_PICK lane=", map.get("lane"), " pref=", PlayerPrefs.get_lane(), " label=", lobby.get("_lane_sub_lab").text)
	print("BTNS=", (lobby.get("_menu_btns") as Array).size(), " diff=", lobby.get("_diff_btn") != null,
		" ip=", lobby.get("_ip_edit") != null, " port=", lobby.get("_port_edit") != null,
		" status=", lobby.get("_status") != null)
	var title = null
	for c in stage.get_children():
		if c is VBoxContainer:
			for cc in c.get_children():
				if cc is Label and cc.text == "荣耀王者":
					title = cc
	print("TITLE_RECT=", (title.get_global_rect() if title != null else Rect2()))
	print("DONE")
	get_tree().quit(0)
